use Test::More;
use Test::Deep;

# Test that we can load the IR modules
use_ok('Chalk::IR::Node::Constant');
use_ok('Chalk::IR::Node::Add');
use_ok('Chalk::IR::Node::Subtract');
use_ok('Chalk::IR::Node::Multiply');
