    sub from_json( $class, $json ) {
        my $graph = $class->new();

        # Restore nodes in order
        for my $node_data ( $json->{nodes}->@* ) {
            my $node = Chalk::IR::Node->new(
                id         => $node_data->{id},
                op         => $node_data->{op},
                inputs     => $node_data->{inputs},
                attributes => $node_data->{attributes},
            );
            $graph->add_node($node);
        }

        # Set entry explicitly (in case it's not the first node)
        $graph->set_entry( $json->{entry} );

        return $graph;
    }

    # Linearize graph using reverse postorder traversal
    # Returns array of nodes in execution order
    method linearize() {
        my @postorder;
        my %visited;

        # Depth-first search with postorder recording
        my $visit;
        $visit = sub {
            my ($node_id) = @_;
            return if $visited{$node_id};
            $visited{$node_id} = 1;

            my $node = $nodes->{$node_id};
            return unless $node;

            # Visit all inputs first (dependencies)
            for my $input_id ($node->inputs->@*) {
                next unless defined $input_id;
                next if $input_id eq '__CONTROL_PLACEHOLDER__';
                $visit->($input_id);
            }

            # Add this node after all its inputs
            push @postorder, $node;
        };

        # Start from entry node
        $visit->($entry) if defined $entry;

        # Return in reverse postorder (topological order)
        return reverse @postorder;
    }
}

