        id => 'node_5',
        inputs => ['node_0', 'node_4'],
        value_id => 'node_4',
        control_id => 'node_0',
    );
    $graph->add_node($return);

    # Execute graph
    my $interpreter = Chalk::IR::Interpreter->new(graph => $graph);
    my $result = $interpreter->execute();

    is($result, 42, 'Store 42 at address 100, Load returns 42');
};

done_testing();

