                    push @new_inputs, $final_id;
                } else {
                    push @new_inputs, undef;
                }
            }

            # Apply redirections to attributes (if they contain node references)
            my $new_attributes = $class->_redirect_attributes(
                $old_node->attributes,
                $redirections
