            }
            # Special case: region_id attribute (used in Phi nodes)
            elsif ($key eq 'region_id' && defined($value) && exists($redirections->{$value})) {
                $new_attrs{$key} = $redirections->{$value};
            }
            else {
                # Copy as-is for other types
                $new_attrs{$key} = $value;
            }
        }

        return \%new_attrs;
    }
}

