                if ($value_node->op eq 'Constant') {
                    my $val = $value_node->attributes->{value} // 'undef';
                    say "  Constant value: $val";
                }
            }
        }
    }
}

say "\nFound " . scalar(@return_nodes) . " Return nodes after GVN";

